import{_ as e,o as t,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"JD9 删除字符串中出现次数最少的字符","description":"简单 通过率：35.68% 时间限制：1秒 空间限制：32M 知识点 字符串 哈希 描述 实现删除字符串中出现次数最少的字符，若出现次数最少的字符有多个，则把出现次数最少的字符都删除。输出删除这些单词后的字符串，字符串中其它字符保持原来的顺序。 数据范围：输入的字符串长度满足 1。","frontmatter":{"title":"JD9 删除字符串中出现次数最少的字符","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：35.68% 时间限制：1秒 空间限制：32M 知识点 字符串 哈希 描述 实现删除字符串中出现次数最少的字符，若出现次数最少的字符有多个，则把出现次数最少的字符都删除。输出删除这些单词后的字符串，字符串中其它字符保持原来的顺序。 数据范围：输入的字符串长度满足 1。","sidebarWeight":84,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD9 删除字符串中出现次数最少的字符.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD9 删除字符串中出现次数最少的字符.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD9 删除字符串中出现次数最少的字符.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD9 删除字符串中出现次数最少的字符.md"};function s(c,a,i,d,_,l){return t(),o("div",null,[...a[0]||(a[0]=[r('<div><h1 id="jd9-删除字符串中出现次数最少的字符" tabindex="-1">JD9 删除字符串中出现次数最少的字符 <a class="header-anchor" href="#jd9-删除字符串中出现次数最少的字符" aria-label="Permalink to &quot;JD9 删除字符串中出现次数最少的字符&quot;">​</a></h1><blockquote><p>本节目标：理解“JD9 删除字符串中出现次数最少的字符”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：35.68% 时间限制：1秒 空间限制：32M 知识点==字符串====哈希== <strong>描述</strong> 实现删除字符串中出现次数最少的字符，若出现次数最少的字符有多个，则把出现次数最少的字符都删除。输出删除这些单词后的字符串，字符串中其它字符保持原来的顺序。</p></blockquote><p>数据范围：输入的字符串长度满足 1≤<em>n</em>≤20 ，保证输入的字符串中仅出现小写字母 <strong>输入描述：</strong> 字符串只包含小写英文字母, 不考虑非法输入，输入的字符串长度小于等于20个字节。 <strong>输出描述：</strong> 删除字符串中出现次数最少的字符后的字符串。 <strong>示例1</strong> 输入： aabcddd ==复制== 输出： aaddd</p><p>要解决这个问题，我们可以分几个步骤来实现：</p><ol><li><strong>统计每个字符的出现次数</strong>：首先遍历整个字符串，使用一个字典来统计每个字符出现的次数。</li><li><strong>找出出现次数最少的字符</strong>：然后遍历这个字典，找到出现次数最少的字符。注意，可能有多个字符的出现次数都是最小的。</li><li><strong>构建新字符串</strong>：最后，再次遍历原字符串，构建一个新的字符串，只包括那些出现次数不是最少的字符。</li></ol><p>以下是Python代码实现： def remove_least_frequent_chars(s):</p><h1 id="统计每个字符的出现次数" tabindex="-1">统计每个字符的出现次数 <a class="header-anchor" href="#统计每个字符的出现次数" aria-label="Permalink to &quot;统计每个字符的出现次数&quot;">​</a></h1><p>char_count = {} for char in s: if char in char_count: char_count[char] += 1 else: char_count[char] = 1</p><h1 id="找出出现次数最少的字符的出现次数" tabindex="-1">找出出现次数最少的字符的出现次数 <a class="header-anchor" href="#找出出现次数最少的字符的出现次数" aria-label="Permalink to &quot;找出出现次数最少的字符的出现次数&quot;">​</a></h1><p>min_count = min(char_count.values())</p><h1 id="构建并返回一个新字符串-只包含出现次数不是最少的字符" tabindex="-1">构建并返回一个新字符串，只包含出现次数不是最少的字符 <a class="header-anchor" href="#构建并返回一个新字符串-只包含出现次数不是最少的字符" aria-label="Permalink to &quot;构建并返回一个新字符串，只包含出现次数不是最少的字符&quot;">​</a></h1><p>return &#39;&#39;.join(char for char in s if char_count[char] != min_count)</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>s = input()</p><h1 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h1><p>print(remove_least_frequent_chars(s))</p><p>这段代码首先统计了字符串<code>s</code>中每个字符的出现次数，然后找到了出现次数最少的字符的出现次数<code>min_count</code>。最后，通过列表解析式，它构建了一个新的字符串，只包括那些其出现次数不等于<code>min_count</code>的字符，从而实现了删除出现次数最少的字符的功能。</p></div>',1)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
